// Ten to One — tiny Node server. No dependencies: Node's built-in http + node:sqlite (Node 22.13+ / 24).
// Serves public/index.html and a small JSON API. Profiles live in one SQLite file (put it on a Railway Volume).

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');

const PORT = Number(process.env.PORT) || 3000;
const DATA_DIR = process.env.DATA_DIR || (fs.existsSync('/data') ? '/data' : path.join(__dirname, 'data'));
const ADMIN_KEY = process.env.ADMIN_KEY || '';
const MAX_PROFILES = 2000;
const MAX_BODY = 12 * 1024;

fs.mkdirSync(DATA_DIR, { recursive: true });
const db = new DatabaseSync(path.join(DATA_DIR, 'ten-to-one.db'));
db.exec(`
  PRAGMA journal_mode = WAL;
  CREATE TABLE IF NOT EXISTS profiles (
    id TEXT PRIMARY KEY,
    token TEXT NOT NULL,
    json TEXT NOT NULL,
    updated_at INTEGER NOT NULL
  );
  CREATE INDEX IF NOT EXISTS profiles_updated ON profiles(updated_at DESC);
`);
const qList = db.prepare('SELECT id, json, updated_at FROM profiles ORDER BY updated_at DESC LIMIT ?');
const qToken = db.prepare('SELECT token FROM profiles WHERE id = ?');
const qCount = db.prepare('SELECT COUNT(*) AS c FROM profiles');
const qUpsert = db.prepare('INSERT INTO profiles (id, token, json, updated_at) VALUES (?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET json = excluded.json, updated_at = excluded.updated_at WHERE profiles.token = excluded.token');
const qDelete = db.prepare('DELETE FROM profiles WHERE id = ? AND token = ?');
const qDeleteAdmin = db.prepare('DELETE FROM profiles WHERE id = ?');

// The app page. If an index.html file sits next to this file (or in public/), it is used instead,
// so you can edit the page on GitHub later without touching this file.
// ---- the app page, base64-encoded (edit index.html instead of this) ----
const EMBEDDED_PAGE = '';
const HTML_FILE = ['index.html', path.join('public', 'index.html')].map(f => path.join(__dirname, f)).find(f => fs.existsSync(f));
const HTML = HTML_FILE ? fs.readFileSync(HTML_FILE) : Buffer.from(EMBEDDED_PAGE, 'base64');

const LISTS = {
  self:     ['looks','smart','funny','wealthy','tall','outgoing','kind','fit','affectionate','tidy'],
  want:     ['looks','smart','funny','wealthy','tall','outgoing','kind','fit','affectionate','tidy'],
  activities:['tv','outdoors','gym','church','reading','sports','games','cooking','chill','phone'],
  music:    ['country','jazz','pop','retro','rnb','easy','rap','edm','rock','talk'],
  drinks:   ['coffee','beer','water','wine','soda','gatorade','tea','cocktails','milk','energy'],
  foods:    ['mexican','italian','chinese','bbq','burgers','pizza','sushi','seafood','steak','brunch'],
  holidays: ['newyear','valentines','springbreak','july4','halloween','thanksgiving','christmas','stpats','easter','birthday'],
  vacation: ['beach','snow','lake','cruise','city','camping','roadtrip','abroad','themepark','staycation'],
  movies:   ['comedy','horror','action','romance','drama','scifi','doc','animated','thriller','superhero'],
};
const ID_RE = /^p_[a-z0-9]{6,40}$/;
const TOKEN_RE = /^[a-f0-9]{32}$/;

function isPermutation(arr, ids) {
  if (!Array.isArray(arr) || arr.length !== 10) return false;
  const seen = new Set();
  for (const x of arr) { if (!ids.includes(x) || seen.has(x)) return false; seen.add(x); }
  return true;
}
// Whitelist every field; nothing from the client is trusted.
function cleanProfile(p) {
  if (!p || typeof p !== 'object') return null;
  const name = String(p.name || '').trim().slice(0, 24);
  const age = Number(p.age);
  const gender = p.gender === 'M' ? 'M' : p.gender === 'F' ? 'F' : null;
  const seeking = Array.isArray(p.seeking) ? [...new Set(p.seeking.filter(x => x === 'M' || x === 'F'))] : [];
  if (!name || !Number.isInteger(age) || age < 18 || age > 99 || !gender || !seeking.length) return null;
  const ageMin = Math.max(18, Math.min(99, Number(p.ageMin) || 18));
  const ageMax = Math.max(ageMin, Math.min(99, Number(p.ageMax) || 99));
  const bio = String(p.bio || '').trim().slice(0, 80);
  const hue = Number.isFinite(Number(p.hue)) ? ((Number(p.hue) % 360) + 360) % 360 : 0;
  const ranks = {}, done = {};
  for (const key in LISTS) {
    const order = p.ranks && p.ranks[key];
    const isDone = key === 'self' || key === 'want' || !!(p.done && p.done[key]);
    if (isDone && isPermutation(order, LISTS[key])) { ranks[key] = order.slice(); done[key] = true; }
    else if (key === 'self' || key === 'want') return null;
    else { ranks[key] = LISTS[key].slice(); done[key] = false; }
  }
  return { name, age, gender, seeking, ageMin, ageMax, bio, hue, ranks, done };
}

function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'content-type': type, 'cache-control': 'no-store' });
  res.end(typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body));
}
function readJson(req) {
  return new Promise(resolve => {
    let size = 0; const chunks = [];
    req.on('data', c => { size += c.length; if (size > MAX_BODY) { req.destroy(); resolve(null); } else chunks.push(c); });
    req.on('end', () => { try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8'))); } catch { resolve(null); } });
    req.on('error', () => resolve(null));
  });
}
const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  const isAdmin = !!ADMIN_KEY && (req.headers['x-admin-key'] === ADMIN_KEY || url.searchParams.get('key') === ADMIN_KEY);

  if (url.pathname === '/api/profiles') {
    if (req.method === 'GET') {
      const rows = qList.all(MAX_PROFILES);
      return send(res, 200, { profiles: rows.map(r => ({ id: r.id, updatedAt: r.updated_at, ...JSON.parse(r.json) })) });
    }
    if (req.method === 'POST') {
      const body = await readJson(req);
      if (!body || !ID_RE.test(String(body.id)) || !TOKEN_RE.test(String(body.token))) return send(res, 400, { error: 'bad request' });
      const profile = cleanProfile(body.profile);
      if (!profile) return send(res, 400, { error: 'invalid profile' });
      const existing = qToken.get(body.id);
      if (existing && existing.token !== body.token) return send(res, 403, { error: 'not yours' });
      if (!existing && qCount.get().c >= MAX_PROFILES) return send(res, 507, { error: 'full' });
      const now = Date.now();
      qUpsert.run(body.id, body.token, JSON.stringify(profile), now);
      return send(res, 200, { ok: true, updatedAt: now });
    }
    if (req.method === 'DELETE') {
      const body = await readJson(req);
      if (!body || !ID_RE.test(String(body.id))) return send(res, 400, { error: 'bad request' });
      let changes = 0;
      if (isAdmin) changes = qDeleteAdmin.run(body.id).changes;
      else if (TOKEN_RE.test(String(body.token))) changes = qDelete.run(body.id, body.token).changes;
      else return send(res, 400, { error: 'bad request' });
      return changes ? send(res, 200, { ok: true }) : send(res, 404, { error: 'not found' });
    }
    return send(res, 405, { error: 'method not allowed' });
  }

  // /admin?key=YOUR_ADMIN_KEY — lists everyone with a Remove button.
  if (url.pathname === '/admin') {
    if (!isAdmin) return send(res, 401, 'Add ?key=YOUR_ADMIN_KEY to the address. Set ADMIN_KEY in Railway → Variables.', 'text/plain; charset=utf-8');
    const rows = qList.all(MAX_PROFILES);
    const tr = rows.map(r => { const p = JSON.parse(r.json); return `<tr><td>${esc(p.name)}, ${p.age} (${p.gender}→${p.seeking.join('')})</td><td>${esc(p.bio || '')}</td><td>${new Date(r.updated_at).toLocaleString()}</td><td><button data-id="${esc(r.id)}">Remove</button></td></tr>`; }).join('');
    const page = `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ten to One admin</title>
<style>body{font:15px system-ui;margin:24px;color:#231A21}table{border-collapse:collapse;width:100%}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left;vertical-align:top}button{font:inherit;padding:4px 10px}</style>
<h1>${rows.length} profile${rows.length === 1 ? '' : 's'}</h1><table><tr><th>Who</th><th>Bio</th><th>Updated</th><th></th></tr>${tr}</table>
<script>document.addEventListener('click',async e=>{const b=e.target.closest('button[data-id]');if(!b||!confirm('Remove this profile?'))return;const r=await fetch('/api/profiles',{method:'DELETE',headers:{'content-type':'application/json','x-admin-key':${JSON.stringify(ADMIN_KEY)}},body:JSON.stringify({id:b.dataset.id})});if(r.ok)b.closest('tr').remove();else alert('Could not remove');});</script>`;
    return send(res, 200, page, 'text/html; charset=utf-8');
  }

  if (url.pathname === '/health') return send(res, 200, { ok: true, profiles: qCount.get().c });
  if (url.pathname === '/' || url.pathname === '/index.html') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' });
    return res.end(HTML);
  }
  send(res, 404, 'Not found', 'text/plain; charset=utf-8');
});

server.listen(PORT, '0.0.0.0', () => console.log(`Ten to One listening on ${PORT}, data in ${DATA_DIR}`));
